      "items": {
        "type": "string"
      },
      "title": "Exceptions",
      "type": "array"
    }
  },
  "required": [
    "roles",
    "if",
    "then",
    "exceptions"
  ],
  "title": "SplitOutputV2",
  "type": "object"
}

